BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
SELECT is(public.api_schema_ready(),true,'Memory/export catalog is ready');
REVOKE SELECT(revision) ON public.approved_memories FROM authenticated;
SELECT is(public.api_schema_ready(),false,'Readiness requires memory revision reads');
GRANT SELECT(revision) ON public.approved_memories TO authenticated;
GRANT EXECUTE ON FUNCTION public.account_export_page(text,integer,timestamptz,uuid) TO anon;
SELECT is(public.api_schema_ready(),false,'Readiness rejects anonymous exports');
REVOKE EXECUTE ON FUNCTION public.account_export_page(text,integer,timestamptz,uuid) FROM anon;
SELECT is(public.api_schema_ready(),true,'Restoring export privacy restores readiness');
CREATE TEMP TABLE privacy_results(label text PRIMARY KEY,payload jsonb NOT NULL);
GRANT SELECT,INSERT ON privacy_results TO authenticated;
INSERT INTO auth.users(id,aud,role,email) VALUES
('88888888-8888-4888-8888-888888888888','authenticated','authenticated','privacy-one@example.invalid'),
('99999999-9999-4999-8999-999999999999','authenticated','authenticated','privacy-two@example.invalid');
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"88888888-8888-4888-8888-888888888888","role":"authenticated"}',true);
INSERT INTO privacy_results VALUES('entry',public.entry_create('Fictional export source',gen_random_uuid(),false)->'entry');
INSERT INTO privacy_results VALUES('memory',public.memory_create('Fictional original memory',NULL,true,'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee'));
INSERT INTO privacy_results VALUES('linked',public.memory_create('Fictional linked memory',(SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='entry'),true,gen_random_uuid()));
SELECT is((SELECT payload->>'revision' FROM privacy_results WHERE label='memory'),'1','New memory starts at revision one');
SELECT is((SELECT payload->>'updated_at'=payload->>'created_at' FROM privacy_results WHERE label='memory'),true,'New memory timestamps match');
INSERT INTO privacy_results VALUES('edited',public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Fictional corrected memory',true,1));
SELECT is((SELECT payload->>'revision' FROM privacy_results WHERE label='edited'),'2','Approved correction increments memory revision');
SELECT is((SELECT payload->>'text' FROM privacy_results WHERE label='edited'),'Fictional corrected memory','Correction changes current text');
SELECT is((SELECT payload->'source_entry_id' FROM privacy_results WHERE label='edited'),'null'::jsonb,'Correction preserves standalone source');
SELECT is(public.memory_create('Fictional original memory',NULL,true,'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee'),(SELECT payload FROM privacy_results WHERE label='edited'),'Original creation retry returns current memory');
SELECT throws_ok($$SELECT public.memory_create('Fictional corrected memory',NULL,true,'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee')$$,'P0001','conflict','Edited text cannot replace immutable original replay payload');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Lost edit',true,1)$$,'P0001','conflict','Stale memory edit cannot overwrite current text');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Unapproved edit',false,2)$$,'P0001','bad_request','Memory correction requires fresh explicit approval');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Missing approval',NULL,2)$$,'P0001','bad_request','Null approval is denied');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),repeat(U&'\+01F600',1001),true,2)$$,'P0001','bad_request','Memory edits enforce UTF16 text bounds');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'   ',true,2)$$,'P0001','bad_request','Blank correction is denied');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Bad revision',true,0)$$,'P0001','bad_request','Positive expected revision is mandatory');
SELECT throws_ok($$UPDATE public.approved_memories SET revision=100$$,'42501',NULL,'Users cannot bypass revision checks with direct writes');
SELECT throws_ok($$SELECT public.account_export_page('settings',NULL,NULL,NULL)$$,'P0001','forbidden','Direct export requires recent authentication claims');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp()))-301)))::text,true);
SELECT throws_ok($$SELECT public.account_export_page('settings',NULL,NULL,NULL)$$,'P0001','forbidden','Old sign-in is rejected by direct RPC');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','token_refresh','timestamp',floor(extract(epoch FROM statement_timestamp())))))::text,true);
SELECT throws_ok($$SELECT public.account_export_page('entries',1,NULL,NULL)$$,'P0001','forbidden','Refresh alone cannot authorize export');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp()))+60)))::text,true);
SELECT throws_ok($$SELECT public.account_export_page('entries',1,NULL,NULL)$$,'P0001','forbidden','Future sign-in outside clock allowance is rejected');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp()))::text)))::text,true);
SELECT throws_ok($$SELECT public.account_export_page('entries',1,NULL,NULL)$$,'P0001','forbidden','String timestamp cannot authorize export');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp()))+0.5)))::text,true);
SELECT throws_ok($$SELECT public.account_export_page('entries',1,NULL,NULL)$$,'P0001','forbidden','Fractional sign-in timestamp is rejected');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp())))))::text,true);
INSERT INTO privacy_results VALUES('settings',public.account_export_page('settings',NULL,NULL,NULL));
SELECT is((SELECT payload->>'format_version' FROM privacy_results WHERE label='settings'),'1','Export format is versioned');
SELECT is((SELECT payload->'settings'->>'reflection_enabled' FROM privacy_results WHERE label='settings'),'false','Export does not enable AI');
SELECT ok((SELECT payload ? 'exported_at' FROM privacy_results WHERE label='settings'),'Export includes UTC page time');
SELECT throws_ok($$SELECT public.account_export_page('settings',1,NULL,NULL)$$,'P0001','bad_request','Settings export does not take row pagination');
SELECT throws_ok($$SELECT public.account_export_page('profiles',1,NULL,NULL)$$,'P0001','bad_request','Export section allowlist blocks internal tables');
SELECT throws_ok($$SELECT public.account_export_page('memories',52,NULL,NULL)$$,'P0001','bad_request','Database export row bound includes only one lookahead');
SELECT throws_ok($$SELECT public.account_export_page('entries',1,'infinity',gen_random_uuid())$$,'P0001','bad_request','Infinite export cursor is rejected');
SELECT throws_ok($$SELECT public.account_export_page('entries',1,statement_timestamp(),NULL)$$,'P0001','bad_request','Unpaired export cursor is rejected');
SELECT throws_ok($$SELECT public.account_export_page('entries',0,NULL,NULL)$$,'P0001','bad_request','Zero export row limit is rejected');
SELECT throws_ok($$SELECT public.account_export_page('entries',NULL,NULL,NULL)$$,'P0001','bad_request','Missing direct RPC row limit is rejected');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','99999999-9999-4999-8999-999999999999','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',floor(extract(epoch FROM statement_timestamp())))))::text,true);
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Other owner edit',true,2)$$,'P0001','not_found','Cross-owner memory correction is denied');
SELECT is(jsonb_array_length(public.account_export_page('memories',50,NULL,NULL)->'items'),0,'Export never includes another owners memories');
SELECT is(jsonb_array_length(public.account_export_page('entries',50,NULL,NULL)->'items'),0,'Export never includes another owners journal');
INSERT INTO privacy_results VALUES('other_todo',public.todo_create('Other owners fictional task',gen_random_uuid()));
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','88888888-8888-4888-8888-888888888888','role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp())))))::text,true);
SELECT is(jsonb_array_length(public.account_export_page('todos',50,NULL,NULL)->'items'),0,'Todo export is also owner scoped');
SELECT lives_ok($$SELECT public.settings_update('{"memory_paused":true}',1)$$,'Memory pause can be set before portability request');
INSERT INTO privacy_results VALUES('linked_edited',public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='linked'),'Fictional corrected source memory',true,1));
SELECT is((SELECT payload->'source_entry_id' FROM privacy_results WHERE label='linked_edited'),(SELECT payload->'source_entry_id' FROM privacy_results WHERE label='linked'),'Correction preserves owned source linkage');
INSERT INTO privacy_results VALUES('page',public.account_export_page('memories',1,NULL,NULL));
SELECT is(jsonb_array_length((SELECT payload->'items' FROM privacy_results WHERE label='page')),1,'Memory export page is bounded');
SELECT is(jsonb_array_length(public.account_export_page('memories',1,(SELECT (payload->'items'->0->>'created_at')::timestamptz FROM privacy_results WHERE label='page'),(SELECT (payload->'items'->0->>'id')::uuid FROM privacy_results WHERE label='page'))->'items'),1,'Precise cursor retrieves the next memory');
INSERT INTO privacy_results VALUES('exported',public.account_export_page('memories',50,NULL,NULL));
SELECT is((SELECT item->>'text' FROM privacy_results,jsonb_array_elements(payload->'items') item WHERE label='exported' AND item->>'id'=(SELECT payload->>'id' FROM privacy_results WHERE label='memory')),'Fictional corrected memory','Export contains current correction while memory is paused');
SELECT ok(NOT EXISTS(SELECT 1 FROM privacy_results,jsonb_array_elements(payload->'items') item WHERE label='exported' AND item ?| ARRAY['original_payload','idempotency_key','owner_id','deleted_at']),'Export excludes all private memory metadata');
SELECT lives_ok($$SELECT public.entry_delete((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='entry'))$$,'Deleting source scrubs linked corrected metadata');
SELECT is(jsonb_array_length(public.account_export_page('entries',50,NULL,NULL)->'items'),0,'Entry export excludes deleted entries');
SELECT is(jsonb_array_length(public.account_export_page('memories',50,NULL,NULL)->'items'),1,'Memory export excludes source-deleted memories');
SELECT lives_ok($$SELECT public.product_delete('memories',(SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'))$$,'Edited standalone memory can be forgotten');
SELECT is(jsonb_array_length(public.account_export_page('memories',50,NULL,NULL)->'items'),0,'Export excludes forgotten standalone memories');
SELECT throws_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM privacy_results WHERE label='memory'),'Recreate deleted',true,2)$$,'P0001','not_found','Deleted memory cannot be corrected into existence');
SELECT throws_ok($$SELECT public.memory_create('Fictional original memory',NULL,true,'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee')$$,'P0001','conflict','Deleted edited memory cannot be replayed into existence');
RESET ROLE;
SELECT ok((SELECT bool_and(text IS NULL AND original_payload IS NULL AND source_entry_id IS NULL AND created_at IS NULL AND revision IS NULL AND updated_at IS NULL) FROM public.approved_memories WHERE owner_id='88888888-8888-4888-8888-888888888888'),'Both deletion paths scrub new memory metadata and original content');
UPDATE public.profiles SET status='deleting' WHERE id='88888888-8888-4888-8888-888888888888';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.account_export_page('settings',NULL,NULL,NULL)$$,'P0001','forbidden','Recent sign-in cannot bypass deleting-profile gate');
SELECT throws_ok($$SELECT public.memory_update(gen_random_uuid(),'Cannot create',true,1)$$,'P0001','forbidden','Deleting profiles cannot edit memories');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.account_export_page('settings',NULL,NULL,NULL)$$,'42501',NULL,'Anonymous users cannot export');
SELECT throws_ok($$SELECT public.memory_update(gen_random_uuid(),'Anonymous edit',true,1)$$,'42501',NULL,'Anonymous users cannot correct memories');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
